(124, 'donate_page_support_title', 'Support Medical Care for the Less Privileged', 'Soutenir les soins médicaux pour les moins privilégiés', NULL, '2025-02-21 15:25:41', '2025-02-21 15:25:41'),
(125, 'donate_page_support_descp', 'Every day, countless individuals struggle to access essential medical care due to financial constraints. \r\n\r\nYour donation can provide life-saving treatments, critical medications, and support programs for those in need.\r\n\r\nTogether, we can make healthcare accessible for all—\r\none contribution at a time.', 'Chaque jour, d’innombrables personnes ont du mal à accéder à des soins médicaux essentiels en raison de contraintes financières.\r\n\r\nVotre don peut permettre de fournir des traitements vitaux, des médicaments essentiels et des programmes de soutien aux personnes dans le besoin.\r\n\r\nEnsemble, nous pouvons rendre les soins de santé accessibles à tous, une contribution à la fois.', NULL, '2025-02-21 15:26:35', '2025-02-21 15:26:35'),
(126, 'donate_page_medical_title', 'medical aid \r\nprograms andbeneficiaries', 'Programmes d\'aide médicale et bénéficiaires', NULL, '2025-02-21 15:28:17', '2025-02-21 15:28:17'),
